'use strict';

const assert = require('node:assert');
const createReadingShelf = require('./solution');

assert.strictEqual(typeof createReadingShelf, 'function');

assert.throws(() => createReadingShelf(), TypeError);
assert.throws(() => createReadingShelf({}), TypeError);
assert.throws(() => createReadingShelf([null]), TypeError);
assert.throws(() => createReadingShelf([{ id: 0, title: 'A', pages: 1, status: 'planned' }]), RangeError);
assert.throws(() => createReadingShelf([{ id: Number.MAX_SAFE_INTEGER + 1, title: 'A', pages: 1, status: 'planned' }]), RangeError);
assert.throws(() => createReadingShelf([{ id: '1', title: 'A', pages: 1, status: 'planned' }]), TypeError);
assert.throws(() => createReadingShelf([{ id: 1, title: '', pages: 1, status: 'planned' }]), TypeError);
assert.throws(() => createReadingShelf([{ id: 1, title: 'A', pages: 0, status: 'planned' }]), TypeError);
assert.throws(() => createReadingShelf([{ id: 1, title: 'A', pages: 1.5, status: 'planned' }]), TypeError);
assert.throws(() => createReadingShelf([{ id: 1, title: 'A', pages: 1, status: 'done' }]), TypeError);
assert.throws(() => createReadingShelf([
  { id: 1, title: 'A', pages: 1, status: 'planned' },
  { id: 1, title: 'B', pages: 2, status: 'reading' }
]), RangeError);

const original = { id: 5, title: 'Five', pages: 50, status: 'planned' };
const initial = [
  original,
  { id: 2, title: 'Two', pages: 20, status: 'reading' }
];
const shelf = createReadingShelf(initial);
assert.deepStrictEqual(Object.keys(shelf).sort(), ['add', 'get', 'list', 'remove', 'update']);
for (const name of Object.keys(shelf)) assert.strictEqual(typeof shelf[name], 'function');

original.title = 'Changed';
initial[1].pages = 999;
initial.push({ id: 7, title: 'Injected', pages: 1, status: 'finished' });
assert.deepStrictEqual(shelf.list(), [
  { id: 2, title: 'Two', pages: 20, status: 'reading' },
  { id: 5, title: 'Five', pages: 50, status: 'planned' }
]);

const listed = shelf.list();
listed[0].title = 'Corrupt';
assert.deepStrictEqual(shelf.get(2), { id: 2, title: 'Two', pages: 20, status: 'reading' });
const fetched = shelf.get(5);
fetched.pages = 1;
assert.deepStrictEqual(shelf.get(5), { id: 5, title: 'Five', pages: 50, status: 'planned' });
assert.strictEqual(shelf.get(3), null);
for (const badId of ['2', null, 1.5]) assert.throws(() => shelf.get(badId), TypeError);
for (const badId of [0, -1, Number.MAX_SAFE_INTEGER + 1]) assert.throws(() => shelf.get(badId), RangeError);

const addInput = { title: 'Six', pages: 60, status: 'finished' };
const added = shelf.add(addInput);
assert.deepStrictEqual(added, { id: 6, title: 'Six', pages: 60, status: 'finished' });
addInput.title = 'Mutated';
added.title = 'Also mutated';
assert.strictEqual(shelf.get(6).title, 'Six');
for (const bad of [
  null,
  {},
  { title: 4, pages: 1, status: 'planned' },
  { title: '', pages: 1, status: 'planned' },
  { title: 'X', pages: 0, status: 'planned' },
  { title: 'X', pages: 1.2, status: 'planned' },
  { title: 'X', pages: 1, status: 'other' }
]) assert.throws(() => shelf.add(bad), TypeError);
assert.strictEqual(shelf.get(7), null);

assert.deepStrictEqual(shelf.update(2, {}), { id: 2, title: 'Two', pages: 20, status: 'reading' });
const patch = {};
Object.defineProperty(patch, 'title', { value: 'Two Revised', enumerable: false });
patch.status = 'finished';
const updated = shelf.update(2, patch);
assert.deepStrictEqual(updated, { id: 2, title: 'Two Revised', pages: 20, status: 'finished' });
updated.title = 'Corrupt';
patch.status = 'planned';
assert.deepStrictEqual(shelf.get(2), { id: 2, title: 'Two Revised', pages: 20, status: 'finished' });

const inherited = Object.create({ title: 'Inherited' });
inherited.pages = 25;
assert.deepStrictEqual(shelf.update(2, inherited), {
  id: 2, title: 'Two Revised', pages: 25, status: 'finished'
});
assert.throws(() => shelf.update(2, { unknown: true }), TypeError);
assert.throws(() => shelf.update(2, { title: 'Valid', pages: 0 }), TypeError);
assert.deepStrictEqual(shelf.get(2), { id: 2, title: 'Two Revised', pages: 25, status: 'finished' });
const symbolPatch = { title: 'Nope' };
symbolPatch[Symbol('extra')] = true;
assert.throws(() => shelf.update(2, symbolPatch), TypeError);
const hiddenExtra = {};
Object.defineProperty(hiddenExtra, 'extra', { value: 1, enumerable: false });
assert.throws(() => shelf.update(999, hiddenExtra), TypeError);
assert.throws(() => shelf.update(999, { pages: 0 }), TypeError);
assert.strictEqual(shelf.update(999, { title: 'Valid' }), null);
assert.throws(() => shelf.update(2, null), TypeError);
assert.throws(() => shelf.update(2, []), TypeError);

assert.strictEqual(shelf.remove(5), true);
assert.strictEqual(shelf.remove(5), false);
assert.deepStrictEqual(shelf.add({ title: 'Seven', pages: 70, status: 'planned' }), {
  id: 7, title: 'Seven', pages: 70, status: 'planned'
});
assert.throws(() => shelf.remove(0), RangeError);
assert.throws(() => shelf.remove('7'), TypeError);

const emptyShelf = createReadingShelf([]);
assert.deepStrictEqual(emptyShelf.list(), []);
assert.deepStrictEqual(emptyShelf.add({ title: 'First', pages: 1, status: 'planned' }), {
  id: 1, title: 'First', pages: 1, status: 'planned'
});

const exhausted = createReadingShelf([{
  id: Number.MAX_SAFE_INTEGER,
  title: 'Last',
  pages: 1,
  status: 'planned'
}]);
assert.strictEqual(exhausted.remove(Number.MAX_SAFE_INTEGER), true);
assert.throws(
  () => exhausted.add({ title: 'Impossible', pages: 1, status: 'planned' }),
  RangeError
);
assert.deepStrictEqual(exhausted.list(), []);

