package solution

import (
	"errors"
	"strings"
)

type ReleaseState string
type ReleaseScope string
type ReviewerState string

const (
	StateQueued         ReleaseState = "queued"
	StatePublishing     ReleaseState = "publishing"
	StateReady          ReleaseState = "ready"
	StateFailed         ReleaseState = "failed"
	StateRemovalPending ReleaseState = "removal-pending"
	StateRemoved        ReleaseState = "removed"
	StateSuspended      ReleaseState = "suspended"
	ScopeOrganization   ReleaseScope = "organization"
	ScopeRestricted     ReleaseScope = "restricted"
	ScopePartners       ReleaseScope = "partners"
	ScopeOpen           ReleaseScope = "open"
	ReviewerPending     ReviewerState = "pending"
	ReviewerApproved    ReviewerState = "approved"
	ReviewerDeclined    ReviewerState = "declined"
)

type Release struct {
	ID        string
	State     ReleaseState
	Scope     ReleaseScope
	Reviewers map[string]ReviewerState
}

type Catalog struct{ releases map[string]*Release }

func NewCatalog() *Catalog { return &Catalog{releases: make(map[string]*Release)} }

func cloneRelease(r *Release) Release {
	out := Release{ID: r.ID, State: r.State, Scope: r.Scope, Reviewers: make(map[string]ReviewerState, len(r.Reviewers))}
	for k, v := range r.Reviewers {
		out.Reviewers[k] = v
	}
	return out
}

func (c *Catalog) find(id string) (*Release, error) {
	if c == nil {
		return nil, errors.New("catalog is nil")
	}
	r, ok := c.releases[id]
	if !ok {
		return nil, errors.New("release not found")
	}
	return r, nil
}

func (c *Catalog) Create(id string) (Release, error) {
	if c == nil {
		return Release{}, errors.New("catalog is nil")
	}
	if strings.TrimSpace(id) == "" {
		return Release{}, errors.New("id must not be blank")
	}
	if _, exists := c.releases[id]; exists {
		return Release{}, errors.New("release already exists")
	}
	r := &Release{ID: id, State: StateQueued, Scope: ScopeRestricted, Reviewers: make(map[string]ReviewerState)}
	c.releases[id] = r
	return cloneRelease(r), nil
}

func (c *Catalog) StartPublish(id string) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if r.State != StateQueued {
		return errors.New("release is not queued")
	}
	r.State = StatePublishing
	return nil
}

func (c *Catalog) FinishPublish(id string, succeeded bool) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if r.State != StatePublishing {
		return errors.New("release is not publishing")
	}
	if succeeded {
		r.State = StateReady
	} else {
		r.State = StateFailed
	}
	return nil
}

func (c *Catalog) RequestRemoval(id string) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if r.State == StateRemoved {
		return errors.New("release is removed")
	}
	if r.State == StateRemovalPending {
		return nil
	}
	r.State = StateRemovalPending
	return nil
}

func (c *Catalog) FinishRemoval(id string) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if r.State != StateRemovalPending {
		return errors.New("removal was not requested")
	}
	r.State = StateRemoved
	return nil
}

func (c *Catalog) Suspend(id string) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if r.State != StateReady {
		return errors.New("only ready releases can be suspended")
	}
	r.State = StateSuspended
	return nil
}

func validScope(s ReleaseScope) bool {
	return s == ScopeOrganization || s == ScopeRestricted || s == ScopePartners || s == ScopeOpen
}

func (c *Catalog) SetScope(id string, scope ReleaseScope) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if !validScope(scope) {
		return errors.New("invalid scope")
	}
	r.Scope = scope
	return nil
}

func (c *Catalog) AddReviewer(id, reviewer string) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if strings.TrimSpace(reviewer) == "" {
		return errors.New("reviewer must not be blank")
	}
	if _, exists := r.Reviewers[reviewer]; exists {
		return errors.New("reviewer already exists")
	}
	r.Reviewers[reviewer] = ReviewerPending
	return nil
}

func (c *Catalog) SetReviewerState(id, reviewer string, state ReviewerState) error {
	r, err := c.find(id)
	if err != nil {
		return err
	}
	if state != ReviewerApproved && state != ReviewerDeclined {
		return errors.New("invalid reviewer state")
	}
	if _, exists := r.Reviewers[reviewer]; !exists {
		return errors.New("reviewer not found")
	}
	r.Reviewers[reviewer] = state
	return nil
}

func (c *Catalog) Get(id string) (Release, bool) {
	if c == nil {
		return Release{}, false
	}
	r, ok := c.releases[id]
	if !ok {
		return Release{}, false
	}
	return cloneRelease(r), true
}

