package solution

import "testing"

const (
	testQueued         ReleaseState = "queued"
	testPublishing     ReleaseState = "publishing"
	testReady          ReleaseState = "ready"
	testFailed         ReleaseState = "failed"
	testRemovalPending ReleaseState = "removal-pending"
	testRemoved        ReleaseState = "removed"
	testSuspended      ReleaseState = "suspended"

	testOrganization ReleaseScope = "organization"
	testRestricted   ReleaseScope = "restricted"
	testPartners     ReleaseScope = "partners"
	testOpen         ReleaseScope = "open"

	testReviewerPending  ReviewerState = "pending"
	testReviewerApproved ReviewerState = "approved"
	testReviewerDeclined ReviewerState = "declined"
)

func TestReleaseCreateDefaultsDuplicatesAndBlankIDs(t *testing.T) {
	c := NewCatalog()
	created, err := c.Create("release-1")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if created.ID != "release-1" || created.State != testQueued || created.Scope != testRestricted {
		t.Fatalf("unexpected new release: %#v", created)
	}
	if created.Reviewers == nil || len(created.Reviewers) != 0 {
		t.Fatalf("new reviewer map = %#v, want non-nil empty map", created.Reviewers)
	}
	if _, err := c.Create("release-1"); err == nil {
		t.Fatal("duplicate release unexpectedly accepted")
	}
	for _, id := range []string{"", " ", "\t\n"} {
		if _, err := c.Create(id); err == nil {
			t.Errorf("blank ID %q unexpectedly accepted", id)
		}
	}
	if _, ok := c.Get(""); ok {
		t.Fatal("blank missing ID unexpectedly found")
	}
}

func TestReleasePublishingTransitions(t *testing.T) {
	c := NewCatalog()
	if _, err := c.Create("success"); err != nil {
		t.Fatal(err)
	}
	if err := c.StartPublish("success"); err != nil {
		t.Fatalf("StartPublish: %v", err)
	}
	assertReleaseState(t, c, "success", testPublishing)
	if err := c.StartPublish("success"); err == nil {
		t.Fatal("second StartPublish unexpectedly succeeded")
	}
	assertReleaseState(t, c, "success", testPublishing)
	if err := c.FinishPublish("success", true); err != nil {
		t.Fatalf("FinishPublish success: %v", err)
	}
	assertReleaseState(t, c, "success", testReady)
	if err := c.FinishPublish("success", false); err == nil {
		t.Fatal("FinishPublish from ready unexpectedly succeeded")
	}
	assertReleaseState(t, c, "success", testReady)

	if _, err := c.Create("failure"); err != nil {
		t.Fatal(err)
	}
	if err := c.StartPublish("failure"); err != nil {
		t.Fatal(err)
	}
	if err := c.FinishPublish("failure", false); err != nil {
