package solution

import (
	"math/big"
	"testing"
)

func TestCollectionPercentSpecifiedCases(t *testing.T) {
	max := ^uint64(0)
	cases := []struct {
		name         string
		live, target uint64
		want         int
	}{
		{"target below live", 100, 99, 0},
		{"target equals live", 100, 100, 0},
		{"fraction floors", 3, 4, 33},
		{"larger fraction floors", 3, 5, 66},
		{"one hundred percent", 25, 50, 100},
		{"clamped", 1, max, 10000},
		{"maximum live", max, max, 0},
		{"overflowing remainder product", uint64(1) << 63, max, 99},
		{"large nontrivial operands", max/3 + 1, max, 199},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := CollectionPercent(tc.live, tc.target)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tc.want {
				t.Fatalf("CollectionPercent(%d, %d) = %d, want %d", tc.live, tc.target, got, tc.want)
			}
		})
	}
}

func TestCollectionPercentZeroLiveErrors(t *testing.T) {
	for _, target := range []uint64{0, 1, ^uint64(0)} {
		got, err := CollectionPercent(0, target)
		if err == nil {
			t.Errorf("target %d: expected error", target)
		}
		if got != 0 {
			t.Errorf("target %d: got %d, want zero", target, got)
		}
	}
}

func TestCollectionPercentAgainstArbitraryPrecisionArithmetic(t *testing.T) {
	max := ^uint64(0)
	inputs := [][2]uint64{
		{max/2 + 1, max},
		{max/7 + 1, max - 3},
		{max/101 + 1, max},
		{1000000000000000000, 18446744073709551615},
		{999999999999999937, 1000000000000000000},
	}
	for _, input := range inputs {
		want := exactCollectionPercent(input[0], input[1])
		got, err := CollectionPercent(input[0], input[1])
		if err != nil {
			t.Fatalf("CollectionPercent(%d, %d): %v", input[0], input[1], err)
		}
		if got != want {
			t.Errorf("CollectionPercent(%d, %d) = %d, want %d", input[0], input[1], got, want)
		}
	}
}

func exactCollectionPercent(live, target uint64) int {
	if target <= live {
		return 0
	}
	delta := new(big.Int).Sub(new(big.Int).SetUint64(target), new(big.Int).SetUint64(live))
	delta.Mul(delta, big.NewInt(100))
	delta.Quo(delta, new(big.Int).SetUint64(live))
	capValue := big.NewInt(10000)
	if delta.Cmp(capValue) > 0 {
		return 10000
	}
	return int(delta.Int64())
}

